  unsigned long long t1; asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t1));
  out[blockIdx.x * blockDim.x + tid] = tot;
  if (tid == 0) tim[blockIdx.x] = t1 - t0;
}
extern "C" __global__ void __launch_bounds__(512,1) k4(const float* w1, float* out, unsigned long long* tim, int C, int HS, int Tp, int s1, int nb1) { body<4,0>(w1,out,tim,C,HS,Tp,s1,nb1); }
extern "C" __global__ void __launch_bounds__(512,1) k8(const float* w1, float* out, unsigned long long* tim, int C, int HS, int Tp, int s1, int nb1) { body<8,0>(w1,out,tim,C,HS,Tp,s1,nb1); }
extern "C" __global__ void __launch_bounds__(512,1) k0(const float* w1, float* out, unsigned long long* tim, int C, int HS, int Tp, int s1, int nb1) { body<4,1>(w1,out,tim,C,HS,Tp,s1,nb1); }
